from pathlib import Path
import json,shutil,zipfile,hashlib,html
P=Path(__file__).parent
m=json.loads((P/'manifest.json').read_text());n=len(m['records']);assert n>0
cover='一起听-小红书封面-银紫版.png';shutil.copy2(P/'发布图'/m['records'][0]['file'],P/cover)
zipname=f'一起听与音乐联动-重做{n}张.zip';records=[]
with zipfile.ZipFile(P/zipname,'w',zipfile.ZIP_DEFLATED) as z:
 for r in m['records']:
  p=P/'发布图'/r['file'];data=p.read_bytes();z.writestr(r['file'],data);records.append({'file':r['file'],'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)})
with zipfile.ZipFile(P/zipname) as z:
 assert z.testzip() is None
 assert len(z.infolist())==n
 for r in records:assert hashlib.sha256(z.read(r['file'])).hexdigest()==r['sha256']
(P/'package-checks.json').write_text(json.dumps({'records':records,'zip':zipname,'zipBytes':(P/zipname).stat().st_size,'crc':True},ensure_ascii=False,indent=2))
items=[{'name':r['name'],'file':'发布图/'+r['file']} for r in m['records']]
thumbs=''.join(f'<button class="thumb" data-i="{i}" aria-label="第{i+1}张：{html.escape(r["name"])}"><img src="{html.escape(r["file"])}"><span>{i+1:02d} · {html.escape(r["name"])}</span></button>' for i,r in enumerate(items))
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>一起听 · COUNT张新版</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f0f5;color:#493b54;font-family:'PingFang SC',sans-serif}header{max-width:1060px;margin:36px auto 24px;padding:0 20px}h1{font-family:'Songti SC',serif;font-size:34px;margin:0 0 10px}p{line-height:1.7;color:#74657e}a{color:#665076;text-decoration:none}.links{display:flex;gap:10px;flex-wrap:wrap}.links a,.controls button,.controls a{background:#fff;border:1px solid #d4c9df;padding:10px 14px;border-radius:10px;font-size:14px;color:#675078}.stage{max-width:920px;margin:auto;padding:0 20px}.stage img{display:block;width:100%;height:auto;border-radius:12px;box-shadow:0 15px 40px #493b541c;cursor:zoom-in}.controls{display:flex;gap:8px;align-items:center;justify-content:center;margin:18px 0}.controls strong{font-size:13px;flex:1;text-align:center}.thumbs{max-width:1060px;margin:24px auto 40px;padding:0 20px;display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.thumb{padding:8px;border:1px solid #d3c9dc;border-radius:12px;background:#fff;text-align:left;color:#665573;cursor:pointer}.thumb.on{outline:2px solid #9b82b7}.thumb img{display:block;width:100%;height:auto;border-radius:6px}.thumb span{display:block;font-size:13px;line-height:1.5;margin-top:8px}footer{max-width:1060px;margin:30px auto;padding:0 20px 32px;font-size:13px;color:#86798d}dialog{max-width:none;max-height:none;width:100vw;height:100dvh;padding:0;border:0;background:#efe9f2}dialog::backdrop{background:#0009}.zoomhead{position:fixed;top:12px;right:14px;z-index:4}dialog button{border:1px solid #cbbdd6;border-radius:12px;padding:11px 18px;background:#fff;font-size:16px}dialog img{display:block;width:1200px;max-width:none;height:1600px;margin:60px auto 0} @media(max-width:600px){header{margin-top:22px}h1{font-size:27px}.thumbs{grid-template-columns:repeat(2,1fr);gap:10px}.stage{padding:0 10px}.controls{flex-wrap:wrap}.controls strong{flex-basis:100%;order:-1}}button:disabled{opacity:.35;cursor:default}
</style><header><h1>一起听 · 银紫唱片内页版</h1><p>COUNT张含封面。主要页面重新截全，小功能集中到同页。点图片可放大看原图。</p><nav class="links"><a href="ZIP" download>下载全部COUNT张</a><a href="COVER" download>单独下载封面</a><a href="制作说明.txt">制作说明与截图范围</a><a href="背景提示词.txt">背景提示词（内置生成）</a></nav></header><main class="stage"><img id="main" src=""><div class="controls"><button id="prev">上一张</button><strong id="label"></strong><button id="next">下一张</button><a id="one" download>下载这一张</a></div></main><section class="thumbs">THUMBS</section><footer>界面来自最新公开源码，人物、曲目、对话为隔离演示数据。背景使用内置imagegen；应用界面保持原生截图，没有生成或重画按钮。未修改产品代码、真实账号或存档，未代发小红书。</footer><dialog id="zoom"><div class="zoomhead"><button id="close">收起原图</button></div><img id="zoomimg"></dialog><script>
const items=ITEMS;let current=0;const el=id=>document.getElementById(id);function show(i){current=Math.max(0,Math.min(items.length-1,i));const r=items[current];el('main').src=r.file;el('main').alt=r.name;el('label').textContent=(current+1)+' / '+items.length+' · '+r.name;el('one').href=r.file;el('prev').disabled=current===0;el('next').disabled=current===items.length-1;document.querySelectorAll('.thumb').forEach((n,j)=>n.classList.toggle('on',j===current));}el('prev').onclick=()=>show(current-1);el('next').onclick=()=>show(current+1);document.querySelectorAll('.thumb').forEach(n=>n.onclick=()=>{show(Number(n.dataset.i));el('main').scrollIntoView({behavior:'smooth'});});el('main').onclick=()=>{el('zoomimg').src=items[current].file;el('zoom').showModal();};el('close').onclick=()=>el('zoom').close();document.addEventListener('keydown',e=>{if(el('zoom').open)return;if(e.key==='ArrowRight')show(current+1);if(e.key==='ArrowLeft')show(current-1);});show(0);
</script></html>'''
page=page.replace('ZIP',zipname).replace('COVER',cover).replace('THUMBS',thumbs).replace('ITEMS',json.dumps(items,ensure_ascii=False))
page=page.replace('COUNT',str(n))
(P/'index.html').write_text(page)
contact='<!doctype html><meta charset="utf-8"><style>body{margin:0;padding:24px;background:#e9e2ee;display:grid;grid-template-columns:repeat(3,400px);gap:18px;width:1284px}img{display:block;width:400px;height:533.333px}figure{margin:0}figcaption{font-family:PingFang SC;font-size:16px;line-height:25px;color:#5c466a;margin-top:7px}</style>'+''.join('<figure><img src="'+r['file']+'"><figcaption>'+str(i+1)+' · '+r['name']+'</figcaption></figure>' for i,r in enumerate(items))
(P/'contact.html').write_text(contact)
print(f'Packaged {n} PNGs, cover, verified ZIP and gallery')
